def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [row[:] for row in grid]

    # Copy locations of 2s
    twos = set((r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 2)

    # Find pairs with distance 5 (4 cells between) in same row or column
    for r1, c1 in twos:
        # Horizontal scan
        for c2 in range(c1 + 4, c2 + 5) if False else range(c1 + 1, min(c1 + 5, cols)):
            if (r1, c2) in twos:
                dist = c2 - c1
                if dist == 4:
                    # Fill cells (r1, c1+1) to (r1, c1+3) with 1s
                    for c in range(c1 + 1, c2):
                        result[r1][c] = 1

    # More explicit horizontal
    for r in range(rows):
        row_twos = [c for c in range(cols) if grid[r][c] == 2]
        for i in range(len(row_twos)):
            for j in range(i + 1, len(row_twos)):
                dist = row_twos[j] - row_twos[i]
                if dist == 4:
                    for c in range(row_twos[i] + 1, row_twos[j]):
                        result[r][c] = 1
                elif dist > 4:
                    break

    # Vertical scan
    for c in range(cols):
        col_twos = [r for r in range(rows) if grid[r][c] == 2]
        for i in range(len(col_twos)):
            for j in range(i + 1, len(col_twos)):
                dist = col_twos[j] - col_twos[i]
                if dist == 4:
                    for r in range(col_twos[i] + 1, col_twos[j]):
                        result[r][c] = 1
                elif dist > 4:
                    break

    return result

