# Two points (r1, c1) and (r2, c2) are diagonally aligned if |r1-r2| == |c1-c2|

def is_diagonal(a, b):
    """Check if two points are on a diagonal (slope ±1)."""
    return abs(a[0] - b[0]) == abs(a[1] - b[1])

