def cells_on_segment(p1, p2):
    """Get all cells (including endpoints) on the line segment between p1 and p2."""
    r1, c1 = p1
    r2, c2 = p2
    cells = [p1, p2]

    if r1 == r2:
        start, end = min(c1, c2), max(c1, c2)
        cells = [(r1, c) for c in range(start, end+1)]
    elif c1 == c2:
        start, end = min(r1, r2), max(r1, r2)
        cells = [(r, c1) for r in range(start, end+1)]
    else:
        if abs(r2 - r1) == abs(c2 - c1):
            dr = r2 - r1
            dc = c2 - c1
            steps = abs(dr)
            cells = [(r1 + i * dr // steps, c1 + i * dc // steps) for i in range(steps + 1)]

    return cells

