# So my theory: Fill only between "middle pair" in a symmetric pattern
# 
# For EVEN-length symmetric patterns, there's a middle pair
# For ODD-length patterns, the "middle" is a single element, so nothing to fill between

def transform_v2(grid):
    """Transform: fill 0s between middle pair in symmetric 2-2 patterns."""
    rows = len(grid)
    cols = len(grid[0])
    result = [row[:] for row in grid]

    for r in range(rows):
        twos = sorted([c for c in range(cols) if grid[r][c] == 2])
        if len(twos) >= 2:
            # Check symmetry: sum of elements should match sum of reversed
            is_sym = all(twos[i] + twos[-1-i] == twos[0] + twos[-1] for i in range(len(twos)//2 + 1))
            if is_sym:
                if len(twos) % 2 == 0:
                    # Even length: fill between middle pair
                    mid1_idx = len(twos) // 2 - 1
                    mid2_idx = len(twos) // 2
                    c1, c2 = twos[mid1_idx], twos[mid2_idx]
                    for c in range(c1 + 1, c2):
                        if grid[r][c] == 0:
                            result[r][c] = 1

    for c in range(cols):
        twos = sorted([r for r in range(rows) if grid[r][c] == 2])
        if len(twos) >= 2:
            is_sym = all(twos[i] + twos[-1-i] == twos[0] + twos[-1] for i in range(len(twos)//2 + 1))
            if is_sym:
                if len(twos) % 2 == 0:
                    mid1_idx = len(twos) // 2 - 1
                    mid2_idx = len(twos) // 2
                    r1, r2 = twos[mid1_idx], twos[mid2_idx]
                    for r in range(r1 + 1, r2):
                        if grid[r][c] == 0:
                            result[r][c] = 1

    return result

